def backfill_client_reviews():
    """Preserve legacy review identity, decisions, attribution and evidence on upgrade."""
    import hashlib
    import json
    from uuid import uuid5

    connection = op.get_bind()
    metadata = sa.MetaData()
    requests = sa.Table("human_requests", metadata, autoload_with=connection)
    decisions = sa.Table("human_decisions", metadata, autoload_with=connection)
    empty_schema = {"type": "object", "properties": {}, "additionalProperties": False}
    actions = [
        {
            "action": "ALLOW_COMPLETION",
            "label": "I have handled this report",
            "consequence": "Acknowledges this report; other blockers still apply.",
            "payload_schema": empty_schema,
        },
        {
            "action": "REQUEST_CHANGES",
            "label": "Give guidance and keep review open",
            "consequence": "Saves guidance and wakes once. Acknowledgement is still required.",
            "payload_schema": empty_schema,
        },
    ]
    rows = list(
        connection.execute(
            sa.text(
                "SELECT v.*, r.report, r.source_id AS report_source_id FROM client_reviews v "
                "JOIN client_reports r ON r.id=v.report_id AND r.tenant_id=v.tenant_id "
                "AND r.case_id=v.case_id"
            )
        ).mappings()
    )
    for row in rows:
        request_id = uuid5(row["id"], "human-request")
        connection.execute(
            requests.insert().values(
                id=request_id,
                tenant_id=row["tenant_id"],
                case_id=row["case_id"],
                task_id=row["task_id"],
                kind="REVIEW",
                handler="client_report.v1",
                subject_id=row["id"],
                subject_fingerprint=row["report_fingerprint"],
                question=row["question"],
                context_summary=row["report"].get("message", ""),
                evidence_source_ids=[str(row["report_source_id"])],
                allowed_actions=actions,
                status=row["status"],
                version=row["version"],
                assignee="local-operator",
                dedupe_key=f"client-review/{row['id']}",
                created_at=row["created_at"],
                resolved_at=row["decided_at"] if row["status"] == "RESOLVED" else None,
            )
        )
        sources = connection.execute(
            sa.text(
                "SELECT * FROM sources WHERE tenant_id=:tenant AND case_id=:case "
                "AND kind='CLIENT_REVIEW_DECISION' AND content->>'review_id'=:review"
            ),
            {"tenant": row["tenant_id"], "case": row["case_id"], "review": str(row["id"])},
        ).mappings()
        for source in sources:
            content = source["content"]
            body = content["request"]
            connection.execute(
                decisions.insert().values(
                    id=uuid5(source["id"], "human-decision"),
                    tenant_id=row["tenant_id"],
                    case_id=row["case_id"],
                    request_id=request_id,
                    action=body["decision"],
                    payload={},
                    reason=body["reason"],
                    actor=content.get("actor", "local-operator"),
                    reviewed_fingerprint=row["report_fingerprint"],
                    source_id=source["id"],
                    idempotency_key=source["source_key"].split("/", 2)[-1],
                    request_hash=hashlib.sha256(
                        json.dumps(body, sort_keys=True).encode()
                    ).hexdigest(),
                    created_at=source["created_at"],
                )
            )


